import { spawnSync } from 'node:child_process';
import { mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

// Tiny browser-style recordings, generated by ffmpeg once per process (never committed):
// 4 s of testsrc2 320x180@15 plus a sine tone. mp4 is fragmented like MediaRecorder's output.
export const hasFfmpeg = () => spawnSync('ffmpeg', ['-version'], { stdio: 'ignore' }).status === 0;

// byte-split into n nearly equal parts, like the page's timed chunks (they cut anywhere)
export const split = (buf, n) => {
  const size = Math.ceil(buf.length / n);
  return Array.from({ length: n }, (_, i) => buf.subarray(i * size, (i + 1) * size)).filter((b) => b.length);
};

let cached;
export function fixtures() {
  cached ??= (() => {
    const dir = mkdtempSync(join(tmpdir(), 'cap-fx-'));
    process.on('exit', () => rmSync(dir, { recursive: true, force: true }));
    const src = ['-f', 'lavfi', '-i', 'testsrc2=size=320x180:rate=15', '-f', 'lavfi', '-i', 'sine=frequency=440:sample_rate=48000', '-t', '4'];
    const gen = (file, codec) => {
      const out = join(dir, file);
      const r = spawnSync('ffmpeg', ['-v', 'error', '-y', ...src, ...codec, out], { encoding: 'utf8' });
      if (r.status !== 0) throw new Error(`fixture ${file}: ${r.stderr}`);
      return readFileSync(out);
    };
    const webm = gen('t.webm', ['-c:v', 'libvpx', '-b:v', '300k', '-c:a', 'libopus']);
    const mp4 = gen('t.mp4', ['-c:v', 'libx264', '-preset', 'ultrafast', '-pix_fmt', 'yuv420p', '-c:a', 'aac',
      '-movflags', 'frag_keyframe+empty_moov+default_base_moof']);
    return { webm: split(webm, 6), mp4: split(mp4, 6), webmSmall: split(webm, 40), mp4Small: split(mp4, 40) };
  })();
  return cached;
}
